#!/usr/bin/env python3
"""Export measured configuration links without rewriting inferred benchmark YAML."""
import hashlib,json,re,subprocess
from pathlib import Path
root=Path(__file__).resolve().parents[1];paper=root/'2026-PASC-Hecbench-Julia-paper';data=paper/'research/data/matched_results.json';records=json.loads(data.read_text());out=root/'ontology/studies/julia_abstractions';out.mkdir(parents=True,exist_ok=True);snapshot=out/'base_snapshot';snapshot.mkdir(exist_ok=True);index=[]
for item in records:
 b=item['benchmark'];c=item['config'];d=item['result'];conf=item['configuration_id'];base=root/'ontology/benchmarks'/(b+'.yaml');key=re.sub(r'[^A-Za-z0-9_.-]','_',b+'__'+conf);cost={}
 if base.exists():(snapshot/(b+'.yaml')).write_bytes(base.read_bytes())
 for target in ['ka','jacc']:
  p=root/'.porting-state/porting_logs'/(b+'-julia-'+target)/'manifest.json'
  if p.exists():
   m=json.loads(p.read_text());cost[target]={k:m.get(k) for k in ['candidate_attempts','compiler_checks','compiler_feedback_repairs','runtime_repairs','numerical_repairs','error_tags','translation_tokens','reference_correction','limitations']}
 r={'schema_version':1,'study':'julia_abstractions_100_v1','benchmark_id':b,'configuration_id':conf,'rq_ids':['RQ1','RQ2','RQ3','RQ4','RQ5'],'experiment_ids':['E1','E2','E3','E4','E5'],'base_ontology':{'path':str(base.relative_to(root)),'archived_snapshot':str((snapshot/(b+'.yaml')).relative_to(root)) if base.exists() else None,'sha256':hashlib.sha256(base.read_bytes()).hexdigest() if base.exists() else None,'status':'Automatically inferred; not validated merely by numerical agreement.'},'feature_outcomes_snapshot':'2026-PASC-Hecbench-Julia-paper/research/data/feature_outcomes.json','numerical_contract_audit':'2026-PASC-Hecbench-Julia-paper/research/data/numerical_contract_audit.json','reviewed_source_traits':item.get('reviewed_source_traits'),'configuration_specific_context':d.get('ontology'),'input_and_scope':d.get('input_contract'),'evidence_strength':c.get('numerical_evidence_strength','full_output_artifacts'),'numerical':{'both_variants_verified':d['variant_verified'],'references_agree':d.get('reference_agreement'),'acceptance_atol':c.get('atol'),'acceptance_rtol':c.get('rtol'),'comparisons':d['comparisons']},'execution':{'protocol':d['protocol'],'excluded_trial':1,'retained_trials':[2,3,4,5],'models':{k:{'source_hash':m.get('source_hash'),'adapter_hash':m.get('adapter_hash'),'five_seconds':[t['time_seconds'] for t in m['trials']],'mean_last_four_seconds':m.get('mean_seconds'),'region':m['trials'][0].get('timing_region')} for k,m in d['models'].items()}},'translation_accounting':cost,'provenance':{'run_id':d['run_id'],'portable_result_snapshot':'2026-PASC-Hecbench-Julia-paper/research/data/matched_results.json','snapshot_sha256':hashlib.sha256(data.read_bytes()).hexdigest(),'source_result_sha256':item['result_sha256'],'source_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip()},'causality':'Measured runtime and recorded source traits do not by themselves establish causal bottlenecks.'}
 f=out/(key+'.json');f.write_text(json.dumps(r,indent=2)+'\n');index.append({'benchmark_id':b,'configuration_id':conf,'path':str(f.relative_to(root)),'evidence_strength':r['evidence_strength']})
(out/'index.json').write_text(json.dumps(index,indent=2)+'\n')
tax={}
for line in (root/'AGENT_INSTRUCTIONS_CODEX_Julia.md').read_text().splitlines():
 match=re.match(r'\| \*\*([BNRSPT][0-9])\*\* \| (.*?) \| (.*?) \|',line)
 if match:tax[match[1]]={'bucket':match[2],'meaning':match[3]}
(out/'failure_taxonomy.json').write_text(json.dumps({'source':'AGENT_INSTRUCTIONS_CODEX_Julia.md §5','categories':tax,'measurement':'Eventphase, sourcecandidate ID, checkinvocation, feedbackrepair and outcome must remain separate; acceptedN3/P1 observations are notfailedattempts.','limits':'These categories describe observed translation/measurement events, not inherent framework capabilities.'},indent=2)+'\n')
(out/'README.md').write_text('''# Julia abstraction study layer

Links measured configurations to canonical benchmark IDs and hashes without rewriting automatically inferred ontology/benchmarks records. Generated by tools/export_julia_study_ontology.py from portable paper result snapshots and per-variant local manifests. Keep base ontology claims distinct from reviewed source traits, named input/scope, numerical evidence strength, measured times, and hypotheses.

A benchmark can have several configurations (for example layout AoS/SoA) and each configuration can have different timed regions, logical work, access mapping, and roofline applicability. Never project a compute-kernel roofline onto the original triad host-transfer pipeline. Integer/property benchmarks require appropriate non-FP measurements.

failure_taxonomy.json preserves canonical instruction codes. Failure events link to attempts and configurations; counts require phase attribution and candidate/check deduplication. N3 tolerated drift and P1 disclosed portability adaptations are not failures. Shared setup/reference-correction costs are not original CUDA.jl translation costs. Per-variant partial proxies are not total consumedtokens.

Raw binaries/databases remain local STATE; concise source hashes, configuration contracts, five samples, and portable paper snapshots provide traceability. Profiling CSVs and modeled ceiling equations are in paper/research/data/profiling, separately from required execution timings. Association does not establish causality.
''')
print(json.dumps({'configurations':len(index),'benchmarks':len({r['benchmark_id'] for r in index}),'taxonomy_codes':len(tax)}))
